configuration.tbelScript:
// AlarmMapping: alarm lifecycle events from the ThingsBoard sink -> ThingsBoard alarms.
// No threshold is evaluated here: the alarm consumer decided RAISED or CLEARED.
// The sink sends one telemetry key per alarm type, alarm_<channel>_<severity>, whose
// value is the event as JSON: alarm_id, state, severity, channel, value, threshold, raised_ts, type.
var key = null;
foreach (k : msg.keySet()) {
    if (k.startsWith("alarm_")) {
        key = k;
    }
}
if (key == null) {
    metadata.alarmAction = "NONE";
    return {msg: msg, metadata: metadata, msgType: msgType};
}
var ev = JSON.parse(msg[key]);
// The alarm type, "<channel label> high (warning|critical)", is set by the sink from config/telemetry.yaml.
var type = ev.type;
// Last event applied per alarm type on this device (server attribute alarm_last).
var last = {};
if (metadata.ss_alarm_last != null) {
    last = JSON.parse(metadata.ss_alarm_last);
}
var prev = last[type];
// Apply an event only if it belongs to a newer alarm than the last one applied for
// this type, or if it is the CLEARED of that same alarm. Anything else is a replay
// (at-least-once delivery, or a re-read of the compacted topic) and is dropped.
var apply = false;
if (prev == null) {
    apply = true;
} else if (ev.raised_ts > prev.raised_ts) {
    apply = true;
} else if (ev.raised_ts == prev.raised_ts && prev.state == "RAISED" && ev.state == "CLEARED") {
    apply = true;
}
if (apply) {
    last[type] = {alarm_id: ev.alarm_id, state: ev.state, raised_ts: ev.raised_ts};
    metadata.alarmAction = ev.state;
} else {
    metadata.alarmAction = "DUPLICATE";
}
metadata.alarmType = type;
metadata.alarmSeverity = ev.severity;
metadata.newAlarmLast = JSON.stringify(last);
return {msg: ev, metadata: metadata, msgType: msgType};

configuration.alarmDetailsBuildTbel:
